import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

export interface ReplayRow {
  id: string;
  task_session_id: string;
  setup_id: string;
  attempt: number;
  cost_usd: number | null;
  hidden_pass: boolean | null;
