type CostRow = { source: string; setup: string; costUsd: number | null };

function replayEntry(setup: string, costUsd: number | null) {
  return { setup, setup_id: setup, setupId: setup, costUsd, cost_usd: costUsd };
}

function forwardPair(
  oldSetup: string,
  oldCost: number | null,
  newSetup: string,
  newCost: number | null,
) {
  return {
    setupOld: oldSetup,
    setupNew: newSetup,
    setup_old: oldSetup,
    setup_new: newSetup,
    costOld: oldCost,
    costNew: newCost,
    cost_old: oldCost,
    cost_new: newCost,
  };
}

